#include "learning.hpp"
#include <algorithm>
namespace exotic::autonomy::agents {
AgentLearningEngine::AgentLearningEngine(AgentRepository&r,LearningConfig c):repository_(r),config_(c){}
void AgentLearningEngine::update_capability(AgentId id,std::string_view key,PerformanceOutcome outcome,double quality){auto caps=repository_.load_agent_capabilities(id);auto it=std::find_if(caps.begin(),caps.end(),[&](const auto&c){return c.capability_key==key;});if(it==caps.end())return;const bool success=outcome==PerformanceOutcome::Success;const double target=success?config_.success_target:config_.failure_target;it->reliability=clamp_score(it->reliability+config_.reliability_learning_rate*(target-it->reliability));it->proficiency=clamp_score(it->proficiency+config_.proficiency_learning_rate*(clamp_score(quality)-it->proficiency));if(success)++it->successful_uses;else ++it->failed_uses;it->last_validated_at=Clock::now();repository_.save_agent_capability(*it);}
void AgentLearningEngine::record(PerformanceRecord r){if(r.id==0)r.id=repository_.next_performance_record_id();r.quality_score=clamp_score(r.quality_score);r.verification_confidence=clamp_score(r.verification_confidence);repository_.append_performance_record(r);if(!r.capability_key.empty())update_capability(r.agent_id,r.capability_key,r.outcome,r.quality_score);}
void AgentLearningEngine::record_assignment(const WorkAssignment&a,PerformanceOutcome o,double q,double v,std::chrono::milliseconds d,double cost,std::string reason){const double per=a.plan.agent_ids.empty()?0.0:cost/static_cast<double>(a.plan.agent_ids.size());for(auto id:a.plan.agent_ids){if(a.requirement.capabilities.empty())record({0,id,a.id,a.job_id,"",o,q,v,d,per,reason,Clock::now()});else for(const auto&c:a.requirement.capabilities)record({0,id,a.id,a.job_id,c.capability_key,o,q,v,d,per,reason,Clock::now()});}}
}
